ALTER TABLE products ADD COLUMN categories text[] NOT NULL DEFAULT ARRAY['games'];
CREATE INDEX products_categories ON products USING GIN(categories);
ALTER TABLE banners ADD COLUMN thumbnail_url text;
CREATE TABLE home_categories (slug text PRIMARY KEY, label text NOT NULL, icon_url text NOT NULL, position int NOT NULL);
CREATE TABLE home_product_groups (group_slug text NOT NULL, product_id bigint NOT NULL REFERENCES products(id), position int NOT NULL, PRIMARY KEY(group_slug,product_id));
UPDATE banners SET active=false WHERE title='Your next adventure. For less.';
UPDATE products SET categories=categories||ARRAY['steam'] WHERE platform_id=(SELECT id FROM platforms WHERE slug='steam');
UPDATE products SET categories=categories||ARRAY['xbox'] WHERE platform_id=(SELECT id FROM platforms WHERE slug='xbox') AND NOT categories @> ARRAY['xbox'];
UPDATE home_blocks SET position=0 WHERE type='banner';
UPDATE home_blocks SET title='Top games',position=3 WHERE type='best_sellers';
UPDATE home_blocks SET position=5 WHERE type='deals';
