INSERT INTO products(slug,name,description,cover_url,developer,platform_id,categories,sales_count) VALUES('psn-card-100-usd','PlayStation Network Card 100 USD (USA) PSN Key UNITED STATES','Demo listing. Simulated purchase and test key delivery only.','/reference/products/product-1.webp','Digital edition',(SELECT id FROM platforms WHERE slug='psn'),ARRAY['gaming-ecards','psn'],16000);
INSERT INTO home_product_groups SELECT 'recommended',id,0 FROM products WHERE slug='psn-card-100-usd';
INSERT INTO offers(product_id,seller_id,region_id,price_cents,old_price_cents) SELECT p.id,s.id,r.id,8745,9800 FROM products p CROSS JOIN sellers s CROSS JOIN regions r WHERE p.slug='psn-card-100-usd' AND s.name='GameNest' AND r.slug='us';
INSERT INTO key_inventory(offer_id,key_value) SELECT o.id,'TEST-'||upper(substr(md5(o.id::text||'-replica-'||n::text),1,12)) FROM offers o JOIN products p ON p.id=o.product_id CROSS JOIN generate_series(1,15)n WHERE p.slug='psn-card-100-usd';
